using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioNativeTransformPerformance {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic;static AnimationStudioWindow controller;static MashBoxStudioViewport view;static StudioModelEditor editor;static Vector2[] candidates;static Vector2 start,last,sent;static int hot,nearest,moveControl,phase,sample,axis;static readonly Tool[] tools={Tool.Move,Tool.Rotate,Tool.Scale,Tool.Move};static List<Vector2> picks=new List<Vector2>();static double deadline;static Vector3[] original;static HashSet<int> selected;static StringBuilder report=new StringBuilder();static List<double> dragTimes=new List<double>(),frameTimes=new List<double>();
 static void Before(SceneView s){if(s!=view)return;var center=editor.EditingPivotPosition;float size=HandleUtility.GetHandleSize(center)*StudioSettings.Current.handleSize;candidates=new[]{HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.5f),HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.7f),HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.9f),HandleUtility.WorldToGUIPoint(center)};}
 static void After(SceneView s){if(s!=view)return;hot=GUIUtility.hotControl;nearest=HandleUtility.nearestControl;moveControl=(int)typeof(StudioModelEditor).GetField("moveDragControl",F).GetValue(editor);}
 public static void Run(){EditorApplication.delayCall+=Begin;}
 static void Begin(){try{StudioMoveDragValidation.Validate();var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FrameProbe.fbx");var doc=StudioModelDocument.Import(model,"Assets/NativeMoveFrame.asset");controller=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(controller,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(controller,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(controller,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==controller);view.position=new Rect(0,0,1500,950);editor=(StudioModelEditor)typeof(AnimationStudioWindow).GetField("modelEditor",F).GetValue(controller);editor.SelectObject(editor.Document.nodes.FindIndex(n=>n.name=="Body"&&n.mesh));typeof(StudioModelEditor).GetField("mode",F).SetValue(editor,StudioModelEditor.ComponentMode.Vertex);typeof(StudioModelEditor).GetField("tool",F).SetValue(editor,Tool.Move);typeof(StudioModelEditor).GetField("local",F).SetValue(editor,false);var points=editor.ActiveMesh.vertices;float median=points.Select(p=>p.x).OrderBy(x=>x).ElementAt(points.Length/2);for(int i=0;i<points.Length;i++)if(points[i].x<median)editor.Components.Add(i);editor.Frame(view);StudioModelEditor.TransformHandleProbe=(kind,center,orientation,size)=>{Event.current.mousePosition=sent;picks.Clear();if(kind!=Tool.Rotate){foreach(float distance in new[]{.45f,.65f,.85f,1f})picks.Add(HandleUtility.WorldToGUIPoint(center+orientation*Vector3.right*size*distance));}else{foreach(float radius in new[]{.9f,1f})for(int plane=0;plane<3;plane++)for(int j=0;j<16;j++){float angle=j*Mathf.PI/8;var a=plane==0?Vector3.up:Vector3.right;var b=plane==2?Vector3.up:Vector3.forward;picks.Add(HandleUtility.WorldToGUIPoint(center+orientation*(a*Mathf.Cos(angle)+b*Mathf.Sin(angle))*size*radius));}}};SceneView.duringSceneGui+=After;deadline=EditorApplication.timeSinceStartup+2;EditorApplication.update+=Tick;}catch(Exception ex){Finish(ex);}}
 static void Send(EventType kind,Vector2 point,Vector2 delta=default){sent=point;view.SendEvent(new Event{type=kind,button=0,mousePosition=new Vector2(700,400),delta=delta});}
 static void Tick(){if(EditorApplication.timeSinceStartup<deadline)return;try{if(phase==0){Send(EventType.Layout,new Vector2(700,400));Send(EventType.Repaint,new Vector2(700,400));var ids=(int[])typeof(StudioModelEditor).GetField("moveHandleIds",F).GetValue(editor);var choices=picks.ToArray();var rotation=(Handles.RotationHandleIds)typeof(StudioModelEditor).GetField("rotationHandleIds",F).GetValue(editor);bool found=false;foreach(var p in choices){Send(EventType.Layout,p);bool match=tools[axis]==Tool.Move?nearest==ids[0]:tools[axis]==Tool.Rotate?(nearest==rotation.x||nearest==rotation.y||nearest==rotation.z):nearest!=21&&nearest!=0;if(match){start=p;found=true;break;}}if(!found)throw new Exception("No native move grip: nearest="+nearest+" ids="+string.Join(",",ids)+" points="+string.Join(";",choices));original=editor.ActiveMesh.vertices;selected=editor.SelectedVertices();Send(EventType.MouseDown,start);if(hot==0||(tools[axis]==Tool.Move&&moveControl!=hot))throw new Exception("Native Move did not capture: hot="+hot+" move="+moveControl);report.AppendLine("Captured "+tools[axis].ToString()+(axis==3?" Local":" World")+" native control "+hot+", selected="+selected.Count);last=start;sample=0;phase=1;return;}
 if(phase==1){var point=start+new Vector2(sample%20*1.5f, sample%20*.4f);var timer=Stopwatch.StartNew();Send(EventType.MouseDrag,point,point-last);double drag=timer.Elapsed.TotalMilliseconds;Send(EventType.Layout,point);Send(EventType.Repaint,point);if(sample>=10){dragTimes.Add(drag);frameTimes.Add(timer.Elapsed.TotalMilliseconds);}last=point;if(++sample<50)return;var result=editor.ActiveMesh.vertices;var first=selected.First();var delta=result[first]-original[first];if(delta.sqrMagnitude<1e-10f)throw new Exception("Native gesture did not move geometry");foreach(int i in Enumerable.Range(0,result.Length))if(!selected.Contains(i)&&(result[i]-original[i]).sqrMagnitude>1e-10f)throw new Exception("Native transform changed unselected positions");Send(EventType.MouseUp,last);if(hot!=0)throw new Exception("Native Move kept mouse capture after release");report.AppendLine(tools[axis].ToString()+(axis==3?" Local":" World")+" drag median ms="+dragTimes.OrderBy(x=>x).ElementAt(dragTimes.Count/2)+" combined median ms="+frameTimes.OrderBy(x=>x).ElementAt(frameTimes.Count/2)+" p95="+frameTimes.OrderBy(x=>x).ElementAt((int)Math.Ceiling(frameTimes.Count*.95)-1));dragTimes.Clear();frameTimes.Clear();if(++axis<4){StudioUndo.PerformUndo();typeof(StudioModelEditor).GetField("tool",F).SetValue(editor,tools[axis]);typeof(StudioModelEditor).GetField("local",F).SetValue(editor,axis==3);phase=0;return;}Finish(null);}}
 catch(Exception ex){Finish(ex);}}
 static void Finish(Exception ex){EditorApplication.update-=Tick;StudioModelEditor.TransformHandleProbe=null;SceneView.duringSceneGui-=After;if(ex!=null)report.AppendLine(ex.ToString());else report.AppendLine("PASS native Move/Rotate/Scale MouseDown/MouseDrag/MouseUp, changed selected geometry, unchanged unselected points and capture release");File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../native-transform-performance.txt")),report.ToString());if(view)view.Close();if(controller)Object.DestroyImmediate(controller);EditorApplication.Exit(ex==null?0:1);}
}
